const contents = $input.all();
const files = contents.filter(c => c.json.type === 'file' && c.json.url);
return files.map(f => ({
  json: f.json,
  pairedItem: f.pairedItem
}));

const lecon = $('Fetch Lecon').first().json;
const allContents = $('Fetch Contents').all().map(i => i.json);
const action = $('Webhook').first().json.body.action || 'explain';
const question = $('Webhook').first().json.body.question || '';

// Get extracted text from files (if any)
let extractedText = "";
try {
  const fileNodes = $('Extract Text').all();
  extractedText = fileNodes.map(f => f.json.text).join('\n\n---\n\n');
} catch (e) {
  extractedText = "No file text extracted.";
}

let context = `LESSON TITLE: ${lecon.titre}\n`;
context += `DESCRIPTION: ${lecon.description || 'N/A'}\n\n`;

// Safety: Truncate extracted text to 15,000 characters to avoid rate limits
const safeText = extractedText.substring(0, 15000);
if (extractedText.length > 15000) {
  context += `--- FULL TEXT CONTENT (TRUNCATED FOR SPEED) ---\n${safeText}\n[...Text truncated due to size...]\n\n`;
} else {
  context += `--- FULL TEXT CONTENT FROM DOCUMENTS ---\n${safeText}\n\n`;
}

context += `--- ADDITIONAL METADATA ---\n`;

allContents.forEach((c, i) => {
  context += `- ${c.type}: ${c.title} (${c.description || ''})\n`;
});

return [{ json: { context, action, question, leconTitle: lecon.titre } }];

